// Additional flowers around center
for (let i = 0; i < flowerCount; i++) {
    const angle = (i / flowerCount) * Math.PI * 2;
    const distance = 150 + Math.random() * 100;

    const x = centerX + Math.cos(angle) * distance;
    const y = centerY + Math.sin(angle) * distance;

    flowers.push({
        x: x,
        y: y,
        petals: 8,
        stemLength: 80 + Math.random() * 60,
        petalWidth: 10 + Math.random() * 15,
        petalHeight: 15 + Math.random() * 20,
        stemColor: '#228B22',
        petalColor: '#FFD700'
    });
}

// Draw each flower
flowers.forEach(flower => {
    // Stem
    ctx.fillStyle = flower.stemColor;
    ctx.fillRect(flower.x, flower.y, 3, flower.stemLength);

    // Petals
    ctx.fillStyle = flower.petalColor;
    for (let i = 0; i < flower.petals; i++) {
        const petalAngle = (i / flower.petals) * Math.PI * 2;
        const startX = flower.x + Math.cos(petalAngle) * 10;
        const startY = flower.y + Math.sin(petalAngle) * 10;

        const endX = startX + Math.cos(petalAngle) * flower.petalWidth;
        const endY = startY + Math.sin(petalAngle) * flower.petalHeight;

        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(endX, endY);
        ctx.lineTo(endX - flower.petalWidth / 2, endY + flower.petalWidth / 2);
        ctx.lineTo(startX - flower.petalWidth / 2, startY + flower.petalWidth / 2);
        ctx.closePath();
        ctx.fill();
    }

    // Center disk
    ctx.fillStyle = '#FFD700';
    ctx.beginPath();
    ctx.arc(flower.x, flower.y, 8, 0, Math.PI * 2);
    ctx.fill();
});

