// Draw cool-toned spiral
const centerX = W / 2;
const centerY = H / 2;
const maxRadius = Math.min(W, H) * 0.4;

// Spiral parameters
const numIterations = 120;
const angleIncrement = Math.PI / 30;
const radiusIncrement = 20;

// Draw spiral
let currentAngle = 0;
let currentRadius = 0;

for (let i = 0; i < numIterations; i++) {
    // Calculate position
    const x = centerX + Math.cos(currentAngle) * currentRadius;
    const y = centerY - Math.sin(currentAngle) * currentRadius;

    // Draw arc
    if (i > 0) {
        ctx.beginPath();
        ctx.arc(x, y, 5, 0, Math.PI * 2);
        ctx.fillStyle = `hsl(${20 + (i * 4) % 180}, 70%, ${(100 - i * 3) % 80}%)`;
        ctx.fill();
    }

    // Update angle and radius
    currentAngle += angleIncrement;
    currentRadius += radiusIncrement;

    // Limit radius to max
    if (currentRadius > maxRadius) {
        currentRadius = maxRadius;
    }
}

// Add gradient background effect
const gradient = ctx.createLinearGradient(0, 0, 0, H);
gradient.addColorStop(0, '#0a0a2a');
gradient.addColorStop(0.5, '#1a1a4a');
gradient.addColorStop(1, '#0a0a2a');

ctx.fillStyle = gradient;
ctx.fillRect(0, 0, W, H);

// Cool tones palette for a fractal spiral
const SKY = '#0c1445';
const GROUND = '#1a3a6a';
const ACCENT = '#4a90e2';
