// Draw a stack of vinyl records
const recordWidth = 200;
const recordHeight = 120;
const stackY = 200;
const stackCount = 5;

// Colors for vinyl and shadow
const vinylColors = ['#2d1b69', '#3a2c75', '#4a3a80', '#5a4a8f', '#6a5a9a'];
const shadowColor = '#1a1a2e';

// Draw records from bottom to top
for (let i = 0; i < stackCount; i++) {
    const x = W/2 - recordWidth/2;
    const y = stackY + i * (recordHeight + 10);

    // Vinyl surface
    ctx.fillStyle = vinylColors[i % vinylColors.length];
    ctx.fillRect(x, y, recordWidth, recordHeight);

    // Shadow under each record
    ctx.fillStyle = shadowColor;
    ctx.fillRect(x, y + recordHeight, recordWidth, 5);

    // Center hole
    ctx.fillStyle = '#2d1b69';
    ctx.beginPath();
    ctx.arc(x + recordWidth/2, y + recordHeight/2, 20, 0, Math.PI * 2);
    ctx.fill();

    // Grooves - horizontal lines
    ctx.strokeStyle = '#3a2c75';
    ctx.lineWidth = 1;
    for (let j = 0; j < 10; j++) {
        const startY = y + recordHeight/2 - 5 + j * 5;
        ctx.beginPath();
        ctx.moveTo(x, startY);
        ctx.lineTo(x + recordWidth, startY);
        ctx.stroke();
    }
}

// Topmost record has a different shadow
